function renderTreks(list=TREKS){const h=escapeHTML,count=$('#category-tabs [data-difficulty=""] span');if(count)count.textContent=String(TREKS.length).padStart(2,'0');$('#trek-grid').innerHTML=list.length?list.map(t=>'<article class="trek-card"><div class="trek-photo" style="background-image:'+h(safeImageCss(t.imageUrl))+'"><span class="trek-tag">'+h(t.difficulty)+' · '+h(t.days)+' days</span><button class="heart '+(state.wishlist.includes('t'+t.id)?'saved':'')+'" data-wish="t'+h(t.id)+'">'+(state.wishlist.includes('t'+t.id)?'♥':'♡')+'</button></div><div class="trek-body"><div class="trek-region">NEPAL · '+h(t.region)+'</div><h3>'+h(t.name)+'</h3><p>'+h(t.description)+'</p><div class="trek-meta"><span>★ '+h(t.rating)+' ('+h(t.reviews)+')</span><span>↟ '+h(npr(t.maxAltitude))+' m</span><span>◷ '+h(t.days)+' days</span></div><div class="trek-bottom"><div><div class="price-label">ESTIMATED FROM</div><div class="price">NPR '+h(npr(t.price))+' <small>/ person</small></div></div><button class="details" data-detail="'+h(t.id)+'">EXPLORE TREK ↗</button></div></div></article>').join(''):'<div class="empty">No treks found. Try another region or category.</div>'}function showTrek(id){const t=TREKS.find(x=>x.id===Number(id));if(!t)return;const h=escapeHTML,days=Array.isArray(t.itinerary)?t.itinerary:[],highlights=Array.isArray(t.highlights)?t.highlights:[],imageStyle=h(safeImageCss(t.imageUrl));modal('<div class="detail-layout"><article class="detail-main"><div class="detail-hero" style="height:210px;background-image:'+imageStyle+';background-position:center;background-size:cover;margin:-30px -30px 20px"></div><div class="eyebrow dark-eyebrow">NEPAL · '+h(String(t.region||'').toUpperCase())+' · ★ '+h(t.rating)+' ('+h(t.reviews)+' REVIEWS)</div><h2>'+h(t.name)+'</h2><p>'+h(t.description)+'</p><div class="form-grid"><div class="list-row">Duration <b>'+h(t.days)+' days</b></div><div class="list-row">Difficulty <b>'+h(t.difficulty)+'</b></div><div class="list-row">Max altitude <b>'+h(npr(t.maxAltitude))+' m</b></div><div class="list-row">Distance <b>~'+h(t.distance)+' km</b></div><div class="list-row">Best season <b>'+h(t.season)+'</b></div><div class="list-row">Estimate <b>NPR '+h(npr(t.price))+' / person</b></div></div><h3>Highlights</h3><p>'+h(highlights.join(' · '))+'</p><h3>Permits</h3><p>'+h(t.permit)+'</p><h3>Day-by-day itinerary</h3><ol class="itinerary">'+days.map(d=>'<li>'+h(d)+'</li>').join('')+'</ol><h3>What to bring</h3><p>Layered clothing, broken-in trekking boots, rain shell, water treatment, sun protection, first-aid basics and personal medication. Ask a local guide to confirm your list.</p><p><b>Includes:</b> sample route planning, local guide suggestion. <b>Not included:</b> international travel, permits, personal insurance and personal expenses. Confirm inclusions with your provider.</p><p class="fine-print">Route, cost, permits and itinerary are sample project data. Verify current conditions before travel.</p></article><aside class="booking-side-card"><span class="booking-side-kicker">PLAN YOUR NEPAL TREK</span><h3>'+h(t.name)+'</h3><div class="booking-side-price">NPR '+h(npr(t.price))+'<small>/ person estimate</small></div><div class="booking-side-meta"><span>◷ '+h(t.days)+' days</span><span>↟ '+h(npr(t.maxAltitude))+' m max</span><span>● '+h(t.difficulty)+'</span></div><button class="button button-dark" data-book="'+h(t.id)+'">Book now ↗</button><p>Tell us your dates and contact details. No account needed.</p><small>Payment is recorded as pending until availability is confirmed.</small></aside></div>');if(location.protocol!=='file:')fetch('/api/catalog/routes/'+encodeURIComponent(id),{cache:'no-store'}).then(r=>r.ok?r.json():[]).then(rows=>{const list=$('#app-modal .itinerary');if(list)list.innerHTML=rows.length?rows.map(r=>'<li>'+h(r.title)+(r.description?' · '+h(r.description):'')+'</li>').join(''):'<li>A detailed daily route is not published yet. Confirm the itinerary with a local guide.</li>'}).catch(()=>{})}function renderGear(){
 const grid=$('#gear-grid');
 if(!grid)return;
 grid.innerHTML=GEAR.filter(g=>Number(g.stock)>0).map(g=>`<article class="gear-card"><div class="gear-image"><img src="${escapeHTML(safeImageUrl(g.imageUrl||image(g.image)))}" alt="${escapeHTML('Close-up of '+g.name)}" loading="lazy" referrerpolicy="no-referrer"><span>RENTAL ESSENTIAL</span></div><div class="gear-info"><small>${escapeHTML(g.category)}</small><h3>${escapeHTML(g.name)}</h3><span class="gear-stock">${escapeHTML(g.stock)} available · Rental stock</span><div class="gear-buy"><strong>NPR ${escapeHTML(npr(g.rentalPrice||g.rent))} <small>/ day</small></strong><button data-gear="${escapeHTML(g.id)}" data-mode="rent">Reserve rental</button></div></div></article>`).join('')||'<div class="empty">No rental equipment is available right now.</div>';
}function updateCounts(){}
$$('#category-tabs button').forEach(b=>b.addEventListener('click',()=>{$$('#category-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');const d=b.dataset.difficulty;renderTreks(d?TREKS.filter(t=>t.difficulty===d||(d==='Challenging'&&t.difficulty==='Expert')):TREKS)}));
$('#hero-search').addEventListener('submit',async e=>{e.preventDefault();const experience=$('#hero-experience').value,season=$('#hero-season').value,button=e.currentTarget.querySelector('button[type="submit"]');if(!experience||!season){toast('Choose your trekking level and season to get a recommendation.');return}const seasonLabel=season==='Current'?'the current trekking season in Nepal today':season.toLowerCase(),prompt=`Recommend Nepal treks for a ${experience.toLowerCase()} trekker during ${seasonLabel}. Use the Him-Path trek catalog. Treat the selected experience level as a safety limit. Suggest only treks suitable for that level, explain the season fit, and include realistic duration and altitude considerations. If the preferred destination has no suitable trek, say so and suggest safer alternatives. Remind the user to check current conditions and permits locally. Keep the answer concise and practical.`;button.disabled=true;button.dataset.originalText=button.innerHTML;button.innerHTML='Finding treks…';try{const response=await fetch('/api/guide/chat',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:prompt})}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.message||'AI recommendations are temporarily unavailable. Please try again.');const answer=escapeHTML(result.answer||'No AI response was returned.').replace(/\n/g,'<br>'),routes=Array.isArray(result.recommendations)?result.recommendations:[],routeCards=routes.map(t=>`<article class="recommendation-trek"><div><b>${escapeHTML(t.name)}</b><small>${escapeHTML(t.difficulty)} · ${escapeHTML(t.days)} days · ${escapeHTML(t.region)}</small></div><button class="button button-dark" type="button" data-detail="${escapeHTML(t.id)}">View trek</button></article>`).join(''),sources=Array.isArray(result.sources)?result.sources:[],sourceLinks=sources.length?`<div class="recommendation-sources"><b>Sources</b>${sources.map(s=>`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.title||s.url)} ↗</a>`).join('')}</div>`:'';modal(`<div class="recommendation-result"><span class="eyebrow dark-eyebrow">HIM-PATH AI RECOMMENDATION</span><h2>Your Nepal trek shortlist</h2><p class="recommendation-input">${escapeHTML(experience)} · ${escapeHTML(season==='Current'?'Current season':season)}</p><div class="recommendation-answer">${answer}</div>${routeCards?`<h3>Matching Him-Path treks</h3><div class="recommendation-list">${routeCards}</div>`:''}${sourceLinks}<p class="fine-print">AI suggestions are a starting point. Confirm permits, weather, trail conditions, and your readiness with local sources before booking.</p></div>`)}catch(error){toast(error.message)}finally{button.disabled=false;button.innerHTML=button.dataset.originalText||'Recommend ↗';delete button.dataset.originalText}});
$$('.region-tile').forEach(b=>b.addEventListener('click',()=>{renderTreks(TREKS.filter(t=>t.region===b.dataset.region));$('#treks').scrollIntoView()}));
$('#trek-grid').addEventListener('click',e=>{if(e.target.dataset.detail)showTrek(e.target.dataset.detail);if(e.target.dataset.wish){const k=e.target.dataset.wish;state.wishlist.includes(k)?state.wishlist=state.wishlist.filter(x=>x!==k):state.wishlist.push(k);save();updateCounts();renderTreks()}});
$$('[data-gear-mode]').forEach(b=>b.addEventListener('click',()=>{$$('[data-gear-mode]').forEach(x=>x.classList.toggle('active',x===b));renderGear(b.dataset.gearMode)}));
$('#gear-grid').addEventListener('click',e=>{
 const button=e.target.closest('[data-gear]');if(!button)return;
 const g=GEAR.find(x=>x.id===Number(button.dataset.gear));if(!g)return;
 const max=Math.max(1,Number(g.stock)||1),today=new Date().toISOString().slice(0,10),dayRate=Number(g.rentalPrice||g.rent);
 modal(`<h2>Rent ${escapeHTML(g.name)}</h2><p>NPR ${npr(dayRate)} per item per day. Requests are confirmed by the Him-Path admin.</p><form id="rental-form"><label class="field">Full name<input name="customerName" autocomplete="name" required maxlength="150"></label><label class="field">Email<input type="email" name="customerEmail" autocomplete="email" required maxlength="190"></label><label class="field">Phone<input type="tel" name="customerPhone" autocomplete="tel" required minlength="7" maxlength="30"></label><div class="form-grid"><label class="field">Start date<input type="date" name="start" min="${today}" required></label><label class="field">Return date<input type="date" name="end" min="${today}" required></label></div><label class="field">Quantity<input type="number" name="qty" value="1" min="1" max="${max}" required></label><label class="field">Payment method<select name="paymentMethod" required><option value="Hand Cash">Hand Cash · pay when collecting gear</option><option value="eSewa">eSewa · pay online after admin approval</option></select></label><div class="booking-total-row"><span>Estimated rental total</span><b id="rental-total">NPR ${npr(dayRate)}</b></div><div class="payment-note">Your rental is not reserved until admin approval. eSewa checkout becomes available after approval; no payment is taken with this request.</div><button class="button button-dark">Request rental ↗</button></form>`);
 const form=$('#rental-form'),start=form.elements.start,end=form.elements.end,qty=form.elements.qty,total=$('#rental-total');
 const refreshTotal=()=>{const days=start.value&&end.value?Math.max(1,Math.floor((new Date(end.value+'T00:00:00')-new Date(start.value+'T00:00:00'))/86400000)+1):1;total.textContent='NPR '+npr(dayRate*days*Math.max(1,Number(qty.value)||1));if(start.value)end.min=start.value};
 start.addEventListener('change',refreshTotal);end.addEventListener('change',refreshTotal);qty.addEventListener('input',refreshTotal);
 form.addEventListener('submit',async ev=>{ev.preventDefault();if(end.value<start.value){toast('Return date must be on or after the start date.');return}const f=new FormData(form),payload={equipmentId:g.id,startDate:f.get('start'),endDate:f.get('end'),quantity:Number(f.get('qty')),customerName:f.get('customerName'),customerEmail:f.get('customerEmail'),customerPhone:f.get('customerPhone'),paymentMethod:f.get('paymentMethod')};try{const response=await fetch('/api/rentals',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(response.status===401&&payload.paymentMethod==='eSewa'?'Sign in with the same email address before requesting eSewa payment.':result.message||'Could not save your rental request.');state.rentals.push({id:result.rentalId,item:g.name,start:payload.startDate,end:payload.endDate,qty:payload.quantity,amount:result.amountNpr,status:result.status,paymentMethod:result.paymentMethod,paymentStatus:result.paymentStatus});save();modal(`<div class="reservation-success"><span class="success-mark">✓</span><h2>Rental request received</h2><p>${escapeHTML(g.name)} · ${payload.quantity} item(s) · ${payload.startDate} to ${payload.endDate}</p><div class="reservation-total">Estimated total: <b>NPR ${npr(result.amountNpr)}</b></div><p>Request #${result.rentalId} · ${escapeHTML(result.paymentMethod)} · ${escapeHTML(result.paymentStatus)}</p><p class="fine-print">The admin will confirm availability. ${payload.paymentMethod==='eSewa'?'After approval, sign in and pay from My account → Equipment Rentals.':'If approved, pay in cash when you collect your equipment.'}</p>${emailNotice(result.emailStatus,payload.customerEmail)}<button class="button button-dark" data-close>Done</button></div>`)}catch(error){toast(error.message)}})
});function planForm(id){
 const t=TREKS.find(x=>x.id===Number(id));
 const now=new Date();
 const todayValue=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
 modal(`<h2>Build a trek plan</h2><p>Choose a trek, start date and group size. Each itinerary day will be dated from your selected start date.</p><form id="plan-form"><label class="field">Trek<select name="trek">${TREKS.map(x=>`<option value="${x.id}" ${t&&x.id===t.id?'selected':''}>${x.name} · ${x.days} days</option>`).join('')}</select></label><div class="form-grid"><label class="field">Start date<input type="date" name="date" min="${todayValue}" required></label><label class="field">Group size<input type="number" name="people" value="1" min="1" max="20" required></label></div><label class="field">Notes<textarea name="notes" rows="2" placeholder="Experience, questions, or preferences"></textarea></label><button class="button button-dark">Create my plan ↗</button></form>`);
 $('#plan-form').addEventListener('submit',e=>{
  e.preventDefault();
  const f=new FormData(e.target),selected=TREKS.find(x=>x.id===Number(f.get('trek'))),startDate=f.get('date');
  if(!selected)return;
  if(!startDate||startDate<todayValue){toast('Choose today or a future start date.');return}
  const row={id:Date.now(),trek:selected.name,date:startDate,people:Number(f.get('people')),notes:f.get('notes'),status:'Planning'};
  state.plans.push(row);save();
  const days=selected.itinerary&&selected.itinerary.length?selected.itinerary:['Confirm a day-by-day route with your local guide.'];
  const firstDay=new Date(`${startDate}T12:00:00`);
  const formatDayDate=offset=>{const date=new Date(firstDay);date.setDate(date.getDate()+offset);return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(date)};
  modal(`<div class="reservation-success"><span class="success-mark">✓</span><h2>Your trek plan is ready</h2><p>${selected.name} · ${row.people} traveler(s) · starts ${formatDayDate(0)}</p><h3>Suggested day-by-day itinerary</h3><ol class="itinerary">${days.map((day,index)=>`<li><strong>Day ${index+1} · ${formatDayDate(index)}</strong><br>${day}</li>`).join('')}</ol><p class="fine-print">Starter plan saved in this browser. Confirm the route, permits and current conditions with a local guide.</p><button class="button button-dark" data-close>Done</button></div>`)
 })
}function openBooking(trekId){const t=TREKS.find(x=>x.id===Number(trekId));if(!t)return;modal(`<h2>Book ${t.name}</h2><p>Estimated trek cost: NPR ${npr(t.price)} per person. Final availability and inclusions are confirmed by the provider.</p><form id="booking-form"><label class="field">Full name<input name="customerName" autocomplete="name" required maxlength="150"></label><label class="field">Email<input type="email" name="customerEmail" autocomplete="email" required maxlength="190"></label><label class="field">Phone<input type="tel" name="customerPhone" autocomplete="tel" required minlength="7" maxlength="30"></label><div class="form-grid"><label class="field">Preferred start date<input type="date" name="date" required></label><label class="field">Travelers<input id="booking-travelers" type="number" name="people" value="1" min="1" max="20" required></label></div><label class="field">Notes for the guide (optional)<textarea name="notes" rows="2" maxlength="1000"></textarea></label><label class="field">Payment method<select name="paymentMethod" required><option value="eSewa">eSewa · pay after confirmation</option><option value="Khalti">Khalti · pay after confirmation</option><option value="Bank transfer">Bank transfer</option><option value="Cash on confirmation">Cash on confirmation</option></select></label><div class="booking-total-row"><span>Estimated total</span><b id="booking-total">NPR ${npr(t.price)}</b></div><div class="payment-note">Choose how you prefer to pay. Your request is saved as payment pending; this college project does not take or charge money.</div><button class="button button-dark">Book now · request confirmation</button></form>`);const form=$('#booking-form'),travelers=$('#booking-travelers'),total=$('#booking-total');travelers.addEventListener('input',()=>{total.textContent=`NPR ${npr(t.price*Math.max(1,Number(travelers.value)||1))}`});form.addEventListener('submit',async ev=>{ev.preventDefault();const f=new FormData(form),payload={trekId:t.id,startDate:f.get('date'),travelers:Number(f.get('people')),customerName:f.get('customerName'),customerEmail:f.get('customerEmail'),customerPhone:f.get('customerPhone'),paymentMethod:f.get('paymentMethod')};try{let result;if(location.protocol==='file:'){result={bookingId:Date.now(),amountNpr:t.price*payload.travelers,paymentMethod:payload.paymentMethod,paymentStatus:'Pending',status:'Requested'}}else{const response=await fetch('/api/bookings',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.message||'Could not save your booking request.')}state.bookings.push({id:result.bookingId,trek:t.name,date:payload.startDate,people:payload.travelers,amount:result.amountNpr,status:result.status});save();modal(`<div class="reservation-success"><span class="success-mark">✓</span><h2>Booking request received</h2><p>${t.name} · ${payload.travelers} traveler(s)</p><div class="reservation-total">Estimated total: <b>NPR ${npr(result.amountNpr)}</b></div><p>Booking #${result.bookingId} · ${result.paymentMethod} · Payment ${result.paymentStatus.toLowerCase()}</p><p class="fine-print">No payment was charged. The provider will confirm availability and share payment instructions.</p>${emailNotice(result.emailStatus,payload.customerEmail)}<button class="button button-dark" data-close>Done</button></div>`)}catch(error){toast(error.message)}})}
