function openGuideProfile(id){const g=GUIDES.find(x=>String(x.id)===String(id));if(!g)return;const h=escapeHTML;modal('<div class="guide-detail"><div class="guide-detail-top"><div class="person-photo person-avatar" aria-hidden="true">'+h(g.name.split(/\s+/).map(part=>part[0]).join(''))+'</div><div><div class="eyebrow dark-eyebrow">LOCAL NEPAL TREK GUIDE</div><h2>'+h(g.name)+'</h2><p>'+h(g.region||'Nepal')+' · '+h(g.experience||'Experienced trekking guide')+' · ★ '+h(g.rating||'New profile')+'</p></div></div><p>'+h(g.bio||'An experienced local guide ready to help you explore Nepal thoughtfully and safely.')+'</p><div class="guide-profile-facts"><p><b>Regions</b><span>'+h(g.region||'Nepal')+'</span></p><p><b>Languages</b><span>'+h(g.languages||'Ask the guide after approval')+'</span></p><p><b>Trek specialties</b><span>'+h(g.specialties||'Nepal trekking')+'</span></p><p><b>Training & certifications</b><span>'+h(g.certifications||'Details available on request')+'</span></p></div><p class="fine-print">Guide phone and email stay private until an admin approves your booking request.</p><button class="button button-dark" type="button" data-request-guide="'+h(g.id)+'">Request this guide ↗</button></div>')}
document.addEventListener('click',e=>{const request=e.target.closest('[data-request-guide]');if(request)openGuideBooking(request.dataset.requestGuide)});
async function openGuideBooking(id){const g=GUIDES.find(x=>String(x.id)===String(id));if(!g)return;if(!userAuth){let profile=null;try{const session=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(session.ok)profile=await session.json()}catch{}if(profile?.role==='USER'){userAuth=true;state.user={email:profile.username,name:profile.username.split('@')[0],role:profile.role};save();syncProfileMenu()}else{modal('<div class="reservation-success"><h2>Sign in to request a guide</h2><p>Your booking will use the email address on your Him-Path account, so you do not need to enter it again.</p><a class="button button-dark" id="guide-sign-in" href="/user-login.html">User sign in ↗</a><p class="fine-print">New here? You can create an account and verify your email before booking.</p></div>');$('#guide-sign-in').addEventListener('click',()=>sessionStorage.setItem('himpathReturnAfterLogin',location.pathname+location.search+location.hash));return}}const now=new Date(),today=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');modal('<h2>Request '+escapeHTML(g.name)+'</h2><p>Send your request to Him-Path for review. Guide contact details remain private until approval.</p><form id="guide-booking-form"><label class="field">Full name<input name="customerName" autocomplete="name" maxlength="150" required></label><label class="field">Phone (optional)<input name="customerPhone" type="tel" maxlength="40"></label><label class="field">Trek you are planning<input name="trekName" maxlength="180" placeholder="For example, Langtang Valley" required></label><div class="form-grid"><label class="field">Preferred start date<input name="startDate" type="date" min="'+today+'" required></label><label class="field">Travelers<input name="travelers" type="number" value="1" min="1" max="20" required></label></div><label class="field">Notes for Him-Path (optional)<textarea name="notes" rows="3" maxlength="1000"></textarea></label><button class="button button-dark">Send booking request</button></form>');const form=$('#guide-booking-form');form.addEventListener('submit',async ev=>{ev.preventDefault();const data=new FormData(form),payload={guideId:Number(id),customerName:data.get('customerName'),customerPhone:data.get('customerPhone'),trekName:data.get('trekName'),startDate:data.get('startDate'),travelers:Number(data.get('travelers')),notes:data.get('notes')};try{const response=await fetch('/api/guide-bookings',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.message||'Could not submit your request. Please try again.');modal('<div class="reservation-success"><span class="success-mark">✓</span><h2>Request sent</h2><p>Your request for '+escapeHTML(g.name)+' has been sent to the Him-Path admin team.</p><p>You will receive an email when it is approved or declined. Guide contact details are shared only after approval.</p><button class="button button-dark" data-close>Done</button></div>')}catch(error){toast(error.message)}})}
