 modal(`<h2>My Him-Path</h2><p>${escapeHTML(state.user.email)}</p><div class="dashboard-layout"><aside class="dashboard-nav">${tabs.map(x=>`<button class="${x===title?'active':''}" data-dash="${key[x]}">${x}</button>`).join('')}</aside><div class="dashboard-content"><h3>${title}</h3>${body}</div></div>`);
