 $$('[data-pay-rental]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;button.textContent='Preparing eSewa…';try{const checkout=await userApi('/api/rentals/'+encodeURIComponent(button.dataset.payRental)+'/esewa-checkout',{method:'POST'});const form=document.createElement('form');form.method='POST';form.action=checkout.actionUrl;for(const[name,value]of Object.entries(checkout.fields)){const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.append(input)}document.body.append(form);form.submit()}catch(error){button.disabled=false;button.textContent='Pay with eSewa';toast(error.message)}}));
