const CHAT_KNOWLEDGE=[{q:'season weather when to go',a:'Spring (roughly March–May) and autumn (roughly September–November) are popular trekking seasons in Nepal. Weather varies by region and year; check local forecasts before setting out.'},{q:'permit permits TIMS',a:'Permit requirements change by region and season. Check with the relevant Nepal tourism authority or a registered local agency before departure.'},{q:'altitude sickness acclimatization',a:'Ascend gradually and plan acclimatization days. Tell your guide if you feel unwell. Severe or worsening symptoms need prompt descent and medical help.'},{q:'equipment gear pack list',a:'Bring layered clothing, broken-in trekking boots, a rain shell, sun protection, water treatment, a headlamp, first-aid basics and personal medication. Adjust for your route and season.'}];
function appendBubble(text,kind){const el=document.createElement('div');el.className=`bubble ${kind}-bubble`;el.textContent=text;$('#chat-messages').append(el);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;return el}async function askGuide(text){if(!text.trim())return;$('.quick-prompts')?.remove();appendBubble(text,'user');$('#chat-input').value='';const wait=appendBubble('Thinking about your trail…','guide');try{const response=await fetch('/api/guide/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text})});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.message||'The trekking assistant is temporarily unavailable.');wait.textContent=data.answer||'I could not prepare a reply. Please try again.';const recommendations=data.recommendations||[];if(recommendations.length){const node=document.createElement('div');node.className='chat-recommendations';node.innerHTML=recommendations.slice(0,3).map(t=>'<a class="chat-rec" href="#treks"><img src="'+escapeHTML(safeImageUrl(t.imageUrl))+'" alt=""><b>'+escapeHTML(t.name)+'</b><span>'+escapeHTML(t.days)+' days · NPR '+escapeHTML(npr(t.price))+'</span></a>').join('');$('#chat-messages').append(node)}if((data.sources||[]).length){const panel=document.createElement('div');panel.className='chat-sources';const heading=document.createElement('strong');heading.textContent='Sources checked';panel.append(heading);for(const source of data.sources){try{const url=new URL(source.url);if(url.protocol!=='https:')continue;const link=document.createElement('a');link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';link.textContent=source.title||url.hostname;panel.append(link)}catch{}}if(panel.children.length>1)$('#chat-messages').append(panel)}$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight}catch(error){wait.textContent=error.message||'The trekking assistant is temporarily unavailable.'}}$('#chat-form').addEventListener('submit',e=>{e.preventDefault();askGuide($('#chat-input').value)});$$('.quick-prompts button').forEach(b=>b.addEventListener('click',()=>askGuide(b.textContent)));
