const aiPanel=$('#ai-panel'),aiFab=$('#ai-fab');function setAiOpen(open){const shown=Boolean(open);aiPanel.classList.toggle('open',shown);aiPanel.setAttribute('aria-hidden',String(!shown));aiFab.setAttribute('aria-expanded',String(shown));if(shown)$('#chat-input').focus()}aiFab.addEventListener('click',()=>setAiOpen(!aiPanel.classList.contains('open')));$('#ai-close').addEventListener('click',()=>setAiOpen(false));$('#ask-ai-link').addEventListener('click',()=>setAiOpen(true));$$('[data-open-ai]').forEach(link=>link.addEventListener('click',e=>{e.preventDefault();setAiOpen(true)}));document.addEventListener('keydown',e=>{if(e.key==='Escape')setAiOpen(false)});$('#app-modal').addEventListener('click',e=>{if(e.target.dataset.detail)showTrek(e.target.dataset.detail)});
function renderGuides(){const grid=$('#guide-grid');if(!grid)return;grid.innerHTML=GUIDES.map(g=>'<article class="person-card guide-profile-card"><div class="person-photo person-avatar" aria-hidden="true">'+escapeHTML(g.name.split(/\s+/).map(part=>part[0]).join(''))+'</div><div><h3>'+escapeHTML(g.name)+'</h3><small>'+escapeHTML(g.region)+'</small><small>'+escapeHTML(g.experience||g.exp||'Local trekking guide')+'</small><span>★ '+escapeHTML(g.rating??g.score??'')+' · Local guide profile</span><button class="button button-dark guide-profile-button" type="button" data-guide-profile="'+escapeHTML(g.id)+'">Explore profile & request booking</button></div></article>').join('')}function renderReviews(){$('#review-grid').innerHTML=REVIEWS.slice(0,4).map(r=>'<article class="review-card"><div class="review-stars">'+('★'.repeat(Math.max(0,Math.min(5,Number(r.rating)||5))))+'</div><blockquote>“'+escapeHTML(r.text)+'”</blockquote><small>'+escapeHTML(r.name)+' · '+escapeHTML(r.route)+'</small></article>').join('')}function searchByDuration(){const q=$('#destination-search').value.toLowerCase(),days=Number($('#hero-days').value);renderTreks(TREKS.filter(t=>(!q||t.region.toLowerCase().includes(q)||t.name.toLowerCase().includes(q))&&(!days||days===5&&t.days<=5||days===10&&t.days>=6&&t.days<=10||days===14&&t.days>10)))}
async function loadSharedCatalog(){if(location.protocol==='file:')return;try{const read=async url=>{const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw new Error('Catalog request failed');return response.json()},[treks,equipment,guides,notices,reviews]=await Promise.all([read('/api/treks'),read('/api/catalog/equipment'),read('/api/catalog/guides'),read('/api/catalog/announcements'),read('/api/reviews')]);TREKS=treks.map(t=>{const old=TREKS.find(x=>x.id===t.id)||{};return {...old,...t,distance:t.distance||old.distance||0,season:t.season||old.season||'Check local seasonal conditions',permit:t.permit||old.permit||'Confirm current permits for this trek before departure.',highlights:t.highlights||old.highlights||['Local trail experience','Himalayan scenery'],itinerary:t.itinerary||old.itinerary||['Review the day-by-day route with your local guide before departure.']}});GEAR=equipment;GUIDES=guides.map(g=>({...g,score:g.rating,exp:g.experience}));REVIEWS=reviews.map(r=>({name:r.username,route:r.route,text:r.reviewText||r.review_text,rating:r.rating}));renderTreks();renderGear();renderGuides();renderReviews();const bar=$('.announcement');bar.replaceChildren();if(notices.length){const icon=document.createElement('span'),link=document.createElement('a');icon.textContent='✳';link.href='#safety';link.textContent='Safety information ↗';bar.append(icon,document.createTextNode(' '+notices[0].title+': '+(notices[0].body||'')+' '),link)}bar.hidden=notices.length===0}catch(error){console.warn('Could not refresh the shared Him-Path catalog.',error)}}
