function initHeroVideo(){const frame=document.getElementById('hero-video');if(!frame)return;frame.style.pointerEvents='none';frame.tabIndex=-1;frame.setAttribute('aria-hidden','true');try{const source=new URL(frame.src);source.searchParams.set('controls','0');source.searchParams.set('disablekb','1');source.searchParams.set('fs','0');source.searchParams.set('autoplay','1');source.searchParams.set('mute','1');source.searchParams.set('loop','1');source.searchParams.delete('playlist');source.searchParams.set('playsinline','1');source.searchParams.set('iv_load_policy','3');source.searchParams.delete('enablejsapi');source.searchParams.delete('origin');source.searchParams.delete('modestbranding');frame.src=source.toString()}catch{}}
