function showTrek(id){const t=TREKS.find(x=>x.id===Number(id));if(!t)return;const h=escapeHTML,days=Array.isArray(t.itinerary)?t.itinerary:[],photos=Array.isArray(t.gallery)&&t.gallery.length?t.gallery:[t.imageUrl],sourceFor=url=>'https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(decodeURIComponent(url.split('/').pop().split('?')[0])).replace(/%20/g,'_');modal('<div class="detail-layout"><article class="detail-main"><div class="detail-hero" style="height:210px;background-image:'+h(safeImageCss(t.imageUrl))+';background-position:center;background-size:cover;margin:-30px -30px 14px"></div><div class="trek-gallery">'+photos.map((url,i)=>'<figure><a href="'+h(sourceFor(url))+'" target="_blank" rel="noopener noreferrer"><img src="'+h(safeImageUrl(url))+'" alt="'+h(t.name+' · photograph from Nepal '+(i+1))+'" loading="lazy"></a><figcaption><a href="'+h(sourceFor(url))+'" target="_blank" rel="noopener noreferrer">Photo '+(i+1)+' · source and license ↗</a></figcaption></figure>').join('')+'</div><div class="eyebrow dark-eyebrow">NEPAL · '+h(String(t.region||'').toUpperCase())+' · ★ '+h(t.rating)+' ('+h(t.reviews)+' REVIEWS)</div><h2>'+h(t.name)+'</h2><p>'+h(t.description)+'</p><div class="form-grid"><div class="list-row">Duration <b>'+h(t.days)+' days</b></div><div class="list-row">Difficulty <b>'+h(t.difficulty)+'</b></div><div class="list-row">Max altitude <b>'+h(npr(t.maxAltitude))+' m</b></div><div class="list-row">Distance <b>~'+h(t.distance)+' km</b></div><div class="list-row">Best season <b>'+h(t.season)+'</b></div><div class="list-row">Estimate <b>NPR '+h(npr(t.price))+' / person</b></div></div><h3>Highlights</h3><p>'+h((t.highlights||[]).join(' · '))+'</p><h3>Permits</h3><p>'+h(t.permit)+'</p><h3>Day-by-day itinerary</h3><ol class="itinerary">'+days.map(d=>'<li>'+h(d)+'</li>').join('')+'</ol>'+(t.itinerarySource?'<p class="fine-print">Route outline based on <a href="'+h(t.itinerarySource)+'" target="_blank" rel="noopener noreferrer">published itinerary source ↗</a>. Daily stages are indicative and may need adjustment.</p>':'')+'<h3>What to bring</h3><p>Layered clothing, broken-in trekking boots, rain shell, water treatment, sun protection and personal medication. Ask a local guide to confirm route-specific needs.</p><p class="fine-print">Route, cost, permits and itinerary are sample planning information. Verify current conditions before travel.</p></article><aside class="booking-side-card"><span class="booking-side-kicker">PLAN YOUR NEPAL TREK</span><h3>'+h(t.name)+'</h3><div class="booking-side-price">NPR '+h(npr(t.price))+'<small>/ person estimate</small></div><div class="booking-side-meta"><span>◷ '+h(t.days)+' days</span><span>↟ '+h(npr(t.maxAltitude))+' m max</span><span>● '+h(t.difficulty)+'</span></div><button class="button button-dark" data-book="'+h(t.id)+'">Book now ↗</button><p>Tell us your dates and contact details. No account needed.</p><small>Payment is recorded as pending until availability is confirmed.</small></aside></div>');if(location.protocol!=='file:')fetch('/api/catalog/routes/'+encodeURIComponent(id),{cache:'no-store'}).then(r=>r.ok?r.json():[]).then(rows=>{const list=$('#app-modal .itinerary');if(list&&rows.length)list.innerHTML=rows.map(r=>'<li>'+h(r.title)+(r.description?' · '+h(r.description):'')+'</li>').join('')}).catch(()=>{})}


